import { Divider, MapleSpendingDonut, Row, Stack, Surface, Text, useQuery } from "@vendo/screen";

export default function SpendingThisMonth() {
  const slices = useQuery("host_getSpendingInsights").data;
  const ranked = slices.slice().sort((left, right) => right.amount - left.amount);
  const total = ranked.reduce((sum, slice) => sum + slice.amount, 0);

  // Maple money is integer CENTS. Hand-rolled rather than toLocaleString:
  // the screen runs in QuickJS, which carries no Intl, so the locale
  // arguments are silently ignored there and $2,850.00 renders as 2850.
  const money = (cents) => {
    const negative = cents < 0;
    const value = negative ? -cents : cents;
    const frac = value % 100;
    let rest = (value - frac) / 100;
    let grouped = "";
    while (rest >= 1000) {
      const chunk = rest % 1000;
      rest = (rest - chunk) / 1000;
      grouped = "," + (chunk < 10 ? "00" + chunk : chunk < 100 ? "0" + chunk : "" + chunk) + grouped;
    }
    return (negative ? "-$" : "$") + rest + grouped + "." + (frac < 10 ? "0" + frac : "" + frac);
  };

  const share = (cents) => total === 0 ? "0.0%" : ((cents / total) * 100).toFixed(1) + "%";
  const capitalize = (word) => word.charAt(0).toUpperCase() + word.slice(1);

  const rowStyle = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "10px 0",
    borderBottom: "1px solid var(--vendo-color-border)",
  };
  const labelStyle = {
    fontFamily: "var(--vendo-font-family)",
    fontSize: "var(--vendo-font-size)",
    color: "var(--vendo-color-text)",
  };
  const rightStyle = {
    display: "flex",
    gap: "12px",
    alignItems: "center",
    fontFamily: "var(--vendo-font-family)",
    fontSize: "var(--vendo-font-size)",
  };
  const amountStyle = {
    color: "var(--vendo-color-text)",
    fontVariantNumeric: "tabular-nums",
    minWidth: "80px",
    textAlign: "right",
  };
  const shareStyle = {
    color: "var(--vendo-color-muted)",
    fontVariantNumeric: "tabular-nums",
    minWidth: "44px",
    textAlign: "right",
    fontSize: "13px",
  };
  const totalRowStyle = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "12px 0 0 0",
  };
  const totalLabelStyle = { ...labelStyle, fontWeight: 600 };
  const totalAmountStyle = { ...labelStyle, fontVariantNumeric: "tabular-nums", fontWeight: 600 };

  return (
    <Stack gap={6}>
      <Stack gap={1}>
        <Text text="Spending This Month" variant="heading" />
        <Text text="Current period · all categories" variant="caption" />
      </Stack>
      <Surface>
        <Stack gap={6}>
          <Row gap={4} justify="center">
            <MapleSpendingDonut slices={ranked} size={220} />
          </Row>
          <Divider />
          <div style={{ width: "100%" }}>
            {ranked.map((slice) => (
              <div style={rowStyle}>
                <span style={labelStyle}>{capitalize(slice.category)}</span>
                <div style={rightStyle}>
                  <span style={amountStyle}>{money(slice.amount)}</span>
                  <span style={shareStyle}>{share(slice.amount)}</span>
                </div>
              </div>
            ))}
            <div style={totalRowStyle}>
              <span style={totalLabelStyle}>Total</span>
              <span style={totalAmountStyle}>{money(total)}</span>
            </div>
          </div>
        </Stack>
      </Surface>
    </Stack>
  );
}
